using Microsoft.EntityFrameworkCore;

public sealed class PaymentWatcher(ShopDb db)
{
    public async Task<bool> WaitAsync(int id, CancellationToken ct)
    {
        for (var attempt = 0; attempt < 20; attempt++)
        {
            // The SELECT runs, but returns the instance tracked on attempt 0
            var payment = await db.Payments.SingleAsync(p => p.Id == id, ct);
            if (payment.Status == PaymentStatus.Confirmed) return true;
            await Task.Delay(TimeSpan.FromSeconds(3), ct);
        }
        return false; // tested: never saw Confirmed
    }
}

using Microsoft.EntityFrameworkCore;

public sealed class PaymentWatcher(IDbContextFactory<ShopDb> factory)
{
    public async Task<bool> WaitAsync(int id, CancellationToken ct)
    {
        for (var attempt = 0; attempt < 20; attempt++)
        {
            // A new, empty context per check builds the entity from the row
            await using var db = await factory.CreateDbContextAsync(ct);
            var payment = await db.Payments.SingleAsync(p => p.Id == id, ct);
            if (payment.Status == PaymentStatus.Confirmed) return true;
            await Task.Delay(TimeSpan.FromSeconds(3), ct);
        }
        return false;
    }
}
